import CustomSelect from "./CustomSelect";
import React, { useRef, useState } from "react";
import API from "../services/api";

/* Dean: create a Full-time / Part-time faculty account. The School ID is generated by the server
   (unique, never typed) and shown right after creation. */
const input = { width: "100%", padding: "9px", borderRadius: "6px", border: "1px solid #d1d5db", marginTop: "4px", boxSizing: "border-box" };
const label = { fontSize: "13px", fontWeight: 600, color: "#333" };

export default function AddFacultyModal({ departments, onClose, onCreated }) {
  const [form, setForm] = useState({ first_name: "", last_name: "", faculty_type: "full_time", email: "", department: departments[0] || "", specializations: "", degree: "", qualifications: "" });
  const fileRef = useRef(null);
  const [reading, setReading] = useState(false);
  const [resumeNote, setResumeNote] = useState(null);   // {name, filled:[...]} after an upload
  const [busy, setBusy] = useState(false);
  const [errors, setErrors] = useState({});
  const [message, setMessage] = useState("");
  const [created, setCreated] = useState(null);

  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  /* Upload a resume: the server reads it and suggests values; the Dean reviews / edits before saving. */
  const readResume = async (file) => {
    if (!file) return;
    setReading(true); setMessage(""); setResumeNote(null);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await API.post("/accounts/dean/parse-resume/", fd, { headers: { "Content-Type": "multipart/form-data" } });
      const r = res.data;
      setForm((f) => ({
        ...f,
        first_name: r.first_name || f.first_name, last_name: r.last_name || f.last_name,
        email: r.email || f.email, degree: r.degree || f.degree,
        specializations: r.specializations?.length ? r.specializations.join(", ") : f.specializations,
        qualifications: r.qualifications || f.qualifications,
      }));
      setResumeNote({ name: file.name, found: r.found || [] });
    } catch (e) {
      setMessage(e.response?.data?.detail || "Could not read that file.");
    } finally { setReading(false); if (fileRef.current) fileRef.current.value = ""; }
  };

  const submit = async () => {
    const errs = {};
    if (!form.first_name.trim()) errs.first_name = "First name is required.";
    if (!form.last_name.trim()) errs.last_name = "Last name is required.";
    if (form.email.trim() && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email.trim())) errs.email = "Enter a valid email address.";
    setErrors(errs); setMessage("");
    if (Object.keys(errs).length) return;
    setBusy(true);
    try {
      const res = await API.post("/accounts/dean/create-faculty/", {
        ...form,
        specializations: form.specializations.split(",").map((s) => s.trim()).filter(Boolean),
      });
      setCreated(res.data);
      onCreated?.();
    } catch (e) {
      const d = e.response?.data;
      if (d?.errors) setErrors(d.errors);
      setMessage(d?.detail || (!e.response ? "Could not reach the server." : "Could not create the account."));
    } finally { setBusy(false); }
  };

  const again = () => { setCreated(null); setForm({ ...form, first_name: "", last_name: "", email: "", specializations: "", degree: "", qualifications: "" }); setResumeNote(null); };

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(15,23,42,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 1000, padding: "12px" }}>
      <div style={{ background: "white", borderRadius: 6, padding: "26px", width: "460px", maxWidth: "100%", maxHeight: "92vh", overflowY: "auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
          <div>
            <h3 style={{ margin: 0, color: "#003366" }}>Add Faculty Account</h3>
            <p style={{ margin: "4px 0 0", fontSize: "13px", color: "#6b7280" }}>The School ID is generated automatically.</p>
          </div>
          <button onClick={onClose} aria-label="Close" style={{ border: "1px solid #d1d5db", background: "white", color: "#374151", fontSize: "13px", fontWeight: 600, padding: "6px 12px", borderRadius: 4, cursor: "pointer" }}>Close</button>
        </div>

        {created ? (
          <div style={{ marginTop: "16px" }}>
            <div style={{ background: "#eafaf0", border: "1px solid #b7e4c7", borderRadius: 6, padding: "14px 16px", color: "#1e5f3a", fontSize: "14px" }}>
              <strong>Account created</strong>
              <table style={{ marginTop: "8px", fontSize: "13px" }}>
                <tbody>
                  <tr><td style={{ paddingRight: "14px", color: "#4b5563" }}>Name</td><td>{created.full_name}</td></tr>
                  <tr><td style={{ color: "#4b5563" }}>School ID</td><td><strong style={{ fontSize: "16px" }}>{created.school_id}</strong></td></tr>
                  <tr><td style={{ color: "#4b5563" }}>Login</td><td>{created.username}</td></tr>
                  <tr><td style={{ color: "#4b5563" }}>Classification</td><td>{created.faculty_classification}</td></tr>
                  <tr><td style={{ color: "#4b5563" }}>Department</td><td>{created.department}</td></tr>
                  {created.email && <tr><td style={{ color: "#4b5563" }}>Email</td><td>{created.email}</td></tr>}
                </tbody>
              </table>
              <div style={{ marginTop: "8px", fontSize: "13px" }}>Default password is the School ID; they must change it on first login.</div>
            </div>
            <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px", marginTop: "16px" }}>
              <button onClick={again} style={{ background: "white", color: "#003366", border: "1px solid #d1d5db", padding: "9px 16px", borderRadius: "6px", cursor: "pointer" }}>Add another</button>
              <button onClick={onClose} style={{ background: "#003366", color: "white", border: "none", padding: "9px 18px", borderRadius: "6px", fontWeight: 600, cursor: "pointer" }}>Done</button>
            </div>
          </div>
        ) : (
          <>
            <div style={{ marginTop: "16px", border: "1px dashed #b6c4d6", borderRadius: 6, padding: "10px 12px", background: "#f9fafb" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: "10px", flexWrap: "wrap" }}>
                <div style={{ fontSize: "13px", color: "#4b5563" }}>
                  <strong style={{ color: "#003366" }}>Resume / CV</strong> (optional): upload a PDF, Word or text file to fill in the form.
                </div>
                <button type="button" onClick={() => fileRef.current?.click()} disabled={reading}
                        style={{ background: "white", color: "#003366", border: "1px solid #003366", padding: "6px 12px", borderRadius: "6px", cursor: "pointer", fontSize: "13px" }}>
                  {reading ? "Reading…" : "Upload resume"}
                </button>
                <input ref={fileRef} type="file" accept=".pdf,.docx,.txt" style={{ display: "none" }}
                       onChange={(e) => readResume(e.target.files?.[0])} />
              </div>
              {resumeNote && (
                <div style={{ marginTop: "8px", fontSize: "13px", color: resumeNote.found.length ? "#1e5f3a" : "#92400e" }}>
                  {resumeNote.found.length
                    ? `Filled in from ${resumeNote.name}. Please review and correct anything below before creating the account.`
                    : `Nothing could be read from ${resumeNote.name}. Please fill in the form by hand.`}
                </div>
              )}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px", marginTop: "16px" }}>
              <div><label style={label}>First name</label><input style={input} value={form.first_name} onChange={set("first_name")} />
                {errors.first_name && <div style={{ color: "#b91c1c", fontSize: "12px" }}>{errors.first_name}</div>}</div>
              <div><label style={label}>Last name</label><input style={input} value={form.last_name} onChange={set("last_name")} />
                {errors.last_name && <div style={{ color: "#b91c1c", fontSize: "12px" }}>{errors.last_name}</div>}</div>
            </div>
            <div style={{ marginTop: "12px" }}>
              <label style={label}>Employment classification</label>
              <CustomSelect style={input} value={form.faculty_type} onChange={set("faculty_type")}>
                <option value="full_time">Full-time</option>
                <option value="part_time">Part-time</option>
              </CustomSelect>
              {errors.faculty_type && <div style={{ color: "#b91c1c", fontSize: "12px" }}>{errors.faculty_type}</div>}
            </div>
            <div style={{ marginTop: "12px" }}>
              <label style={label}>Department</label>
              {departments.length > 1 ? (
                <CustomSelect style={input} value={form.department} onChange={set("department")}>{departments.map((d) => <option key={d} value={d}>{d}</option>)}</CustomSelect>
              ) : (
                <input style={{ ...input, background: "#f3f4f6" }} value={form.department} readOnly />
              )}
              {errors.department && <div style={{ color: "#b91c1c", fontSize: "12px" }}>{errors.department}</div>}
            </div>
            <div style={{ marginTop: "12px" }}>
              <label style={label}>Email (optional)</label>
              <input style={input} type="email" value={form.email} onChange={set("email")} />
              {errors.email && <div style={{ color: "#b91c1c", fontSize: "12px" }}>{errors.email}</div>}
            </div>
            <div style={{ marginTop: "12px" }}>
              <label style={label}>Specialization / field(s) (optional)</label>
              <input style={input} placeholder="e.g. Computer Science, Mathematics (comma-separated)" value={form.specializations} onChange={set("specializations")} />
            </div>
            <div style={{ marginTop: "12px" }}>
              <label style={label}>Degree(s) (optional)</label>
              <input style={input} placeholder="e.g. Master of Science in Information Technology" value={form.degree} onChange={set("degree")} />
            </div>
            <div style={{ marginTop: "12px" }}>
              <label style={label}>Licenses, certifications, trainings (optional)</label>
              <textarea style={{ ...input, minHeight: "58px", fontFamily: "inherit" }} value={form.qualifications} onChange={set("qualifications")} />
            </div>
            {message && <p style={{ marginTop: "12px", fontSize: "13px", color: "#b91c1c" }}>{message}</p>}
            <div style={{ display: "flex", justifyContent: "flex-end", gap: "10px", marginTop: "20px" }}>
              <button onClick={onClose} style={{ background: "white", color: "#111827", border: "1px solid #d1d5db", padding: "9px 18px", borderRadius: "6px", cursor: "pointer" }}>Cancel</button>
              <button onClick={submit} disabled={busy} style={{ background: "#003366", color: "white", border: "none", padding: "9px 20px", borderRadius: "6px", fontWeight: 600, cursor: "pointer" }}>
                {busy ? "Creating…" : "Create account"}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
